import{_ as e,o as a,c as n,a2 as s}from"./chunks/framework.BfI5QxtK.js";const p=JSON.parse('{"title":"Config API","description":"","frontmatter":{},"headers":[],"relativePath":"config.md","filePath":"config.md"}'),t={name:"config.md"};function o(l,i,r,d,c,h){return a(),n("div",null,[...i[0]||(i[0]=[s(`<h1 id="config-api" tabindex="-1">Config API <a class="header-anchor" href="#config-api" aria-label="Permalink to &quot;Config API&quot;">​</a></h1><p>Use <a href="/gnoblin/config/configure"><code>gnoblin.configure</code></a> for settings, named shortcuts and autostart commands. The reference pages list the supported fields and defaults.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><ul><li><a href="/gnoblin/config/configure"><code>gnoblin.configure</code></a> — set compositor, shell, input and window-management options.</li><li><a href="/gnoblin/config/window_rule"><code>gnoblin.window_rule</code></a> — add a window or layer-surface rule.</li><li><a href="/gnoblin/config/permission_rule"><code>gnoblin.permission_rule</code></a> — add a portal permission rule.</li><li><a href="/gnoblin/config/load"><code>gnoblin.load</code></a> — load another Lua config file.</li><li><a href="/gnoblin/config/snapshot"><code>gnoblin.snapshot</code></a> — inspect a copy of the current config.</li><li><a href="/gnoblin/config/array"><code>gnoblin.array</code></a> — mark a Lua table as a list.</li></ul><p>The named views <a href="/gnoblin/config/configure/shortcuts"><code>gnoblin.configure.shortcuts</code></a> and <a href="/gnoblin/config/configure/autostart"><code>gnoblin.configure.autostart</code></a> read or update entries by name. See the <a href="/gnoblin/guides/shortcuts">shortcuts</a> and <a href="/gnoblin/guides/autostart">autostart</a> guides. Lua&#39;s <code>require</code> loader is covered under <a href="/gnoblin/config/load"><code>gnoblin.load</code></a>.</p><h2 id="migrate-older-config-calls" tabindex="-1">Migrate older config calls <a class="header-anchor" href="#migrate-older-config-calls" aria-label="Permalink to &quot;Migrate older config calls&quot;">​</a></h2><p>You can keep existing configs and migrate them a piece at a time. Replace the older named-entry calls with the matching <code>gnoblin.configure</code> map:</p><p>These older functions are deprecated and may be removed at any time. Each config refresh that executes one prints a warning with its migration path. Move to the current forms below.</p><table tabindex="0"><thead><tr><th>Older call</th><th>Current form</th></tr></thead><tbody><tr><td><code>gnoblin.shortcut {name = &quot;terminal&quot;, ...}</code></td><td><code>gnoblin.configure.shortcuts.terminal = {...}</code></td></tr><tr><td><code>gnoblin.autostart {name = &quot;panel&quot;, ...}</code></td><td><code>gnoblin.configure.autostart.panel = {...}</code></td></tr><tr><td><code>gnoblin.remove_shortcut(&quot;terminal&quot;)</code></td><td><code>gnoblin.configure.shortcuts.terminal.enable = false</code></td></tr><tr><td><code>gnoblin.remove_autostart(&quot;panel&quot;)</code></td><td><code>gnoblin.configure.autostart.panel.enable = false</code></td></tr></tbody></table><p>For <code>gnoblin.set</code>, move the values into <code>gnoblin.configure</code> and use the public keys from the reference. For example, change the internal <code>minimize-duration</code> key to <code>minimize_duration</code>:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Older form</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {shell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minimize-duration&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Current form</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {shell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {minimize_duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>Disabling an autostart entry affects future launches; it does not stop a process that is already running.</p><h2 id="first-config" tabindex="-1">First config <a class="header-anchor" href="#first-config" aria-label="Permalink to &quot;First config&quot;">​</a></h2><p>On first login, <code>gnoblin-session</code> copies the packaged reference config to <code>~/.config/gnoblin/init.lua</code> when no Lua or legacy config exists. It does not replace an existing config. Edit that file to configure Gnoblin.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><p>See <a href="/gnoblin/recipes/">configuration recipes</a> for complete examples and the <a href="/gnoblin/guides/window_rules">guides</a> for task-based instructions.</p>`,16)])])}const u=e(t,[["render",o]]);export{p as __pageData,u as default};
